/* Vygenerováno z data/slovnik/kapitola-*.json, neupravovat ručně. */
window.GENAI_SLOVNIK = {"kapitoly":{"1":"Úvod do generativní AI pro testování softwaru","2":"Prompt engineering pro efektivní testování","3":"Řízení rizik generativní AI v testování","4":"Testovací infrastruktura postavená na LLM","5":"Zavedení generativní AI v testovací organizaci"},"pojmy":[{"id":"a-b-testing-of-prompts","en":"A/B testing of prompts","cz":"A/B testování promptů","def":"Porovnání víc verzí promptu podle předem stanovených metrik s cílem vybrat tu lepší.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-2"},{"id":"acceptance-criteria","en":"acceptance criteria","cz":"akceptační kritéria","def":"Podmínky, které musí implementace uživatelského scénáře splnit, aby ji zainteresované strany přijaly. Sylabus je v oddílu 2.2.1 uvádí jako příklad testovacích podmínek, které pomáhá vytvořit GenAI.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-1"},{"id":"accuracy","en":"accuracy","cz":"správnost (accuracy)","def":"Celková správnost výstupu GenAI vůči standardu: testům od odborníka, požadavkům. Příklad: podíl pokrytých specifikovaných požadavků.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"adjust-prompt-length-and-specificity","en":"adjust prompt length and specificity","cz":"úprava délky a konkrétnosti promptu","def":"Experimentování s délkou a podrobností promptu; víc kontextu někdy pomůže, kratší prompt jindy lépe zobecní.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-2"},{"id":"ai-assistant","en":"AI assistant","cz":"AI asistent","def":"Rozhraní zabudované do testovacího nástroje, přes které uživatel pracuje s agenty. Poloautonomně převádí scénáře a požadavky na testware.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"ai-chatbot","en":"AI chatbot","cz":"AI chatbot","def":"Konverzační aplikace, přes kterou uživatel mluví s LLM v přirozeném jazyce a dostává okamžité odpovědi s ohledem na kontext rozhovoru.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-2-2"},{"id":"ai-governance-framework","en":"AI governance framework","cz":"rámec pro správu a řízení AI","def":"Pravidla, role a kontroly, které určují, jak se AI pro daný případ použití smí používat. Zavádí je test manažer.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"ai-literacy","en":"AI literacy","cz":"AI gramotnost","def":"Schopnost rozumět, co AI umí a neumí, bezpečně s ní pracovat a kriticky posoudit její výstup.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"ai-assisted-test-specialist","en":"AI-assisted test specialist","cz":"specialista na testování s podporou AI","def":"Cílová podoba role testera. Spojuje znalost testovacích technik s dovedností vést AI a ověřovat testware, který vytvořila.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"ai-based-risk-management","en":"AI-based risk management","cz":"řízení rizik spojených s AI","def":"Identifikace, analýza a zmírňování rizik, která přináší použití AI v testování. Nová odpovědnost test manažera.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"ai-based-test-strategy","en":"AI-based test strategy","cz":"testovací strategie založená na AI","def":"Testovací strategie, která zahrnuje použití AI. Její vytvoření je nová odpovědnost test manažera.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"assessing-llm-capabilities","en":"assessing LLM capabilities","cz":"posouzení schopností LLM","def":"Kompetence testera určit, co model pro danou úlohu zvládne a co ne, včetně možnosti ho pro úlohu přizpůsobit.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-1"},{"id":"attack-vector","en":"attack vector","cz":"vektor útoku","def":"Cesta, kterou útočník míří na systém. Sylabus uvádí čtyři vektory pro generativní AI v testování.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"authentication","en":"authentication","cz":"autentizace","def":"Ověření, kdo se do systému přihlašuje a k jakým datům má přístup. V architektuře s LLM ji zajišťuje back-end.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"automated-verification","en":"automated verification","cz":"automatická verifikace","def":"Automatická kontrola výsledků agenta, například že vygenerovaný test odkazuje na existující požadavek nebo že defekt není duplicitní.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"autonomous-agent","en":"autonomous agent","cz":"autonomní agent","def":"Agent, který pracuje samostatně s minimálním zásahem člověka a opírá se o předem daná pravidla, učení posilováním a adaptivní zpětnou vazbu.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"back-end","en":"back-end","cz":"back-end (serverová část)","def":"Část infrastruktury, která zpracovává vstup uživatele: ověřuje ho, vyhledává data, připravuje prompt, řídí komunikaci s LLM a upravuje výstup modelu.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"benchmark","en":"benchmark","cz":"benchmark (srovnávací test)","def":"Standardizovaná sada úloh a metrik pro porovnání modelů. Pro testovací úlohy existuje jen málo veřejných benchmarků.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"bias","en":"bias","cz":"zkreslení (bias)","def":"Systematická tendence výstupu LLM upřednostňovat určité informace, postupy nebo předpoklady. Pochází z trénovacích dat.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-1-1"},{"id":"chain-of-thought-reasoning","en":"chain-of-thought reasoning","cz":"uvažování v řetězci kroků","def":"Postup, při kterém model řeší úlohu přes výslovné mezikroky, než dojde k odpovědi.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-3"},{"id":"change-management","en":"change management","cz":"řízení změny","def":"Strukturovaný přístup k zavedení změny v organizaci. U GenAI zahrnuje budování dovedností a vývoj rolí, technickou i organizační stránku.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2"},{"id":"chief-information-security-officer-ciso","en":"Chief Information Security Officer (CISO)","cz":"ředitel bezpečnosti informací","def":"Vedoucí odpovědný za bezpečnost informací v organizaci. Sylabus doporučuje ho zapojit do rozhodování o generativní AI.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"chunking","en":"chunking","cz":"rozdělení na části","def":"Rozdělení velkého dokumentu na menší části (chunks), v sylabu například po 256 až 512 tokenech, kvůli cílenému vyhledání a kontextovému oknu modelu.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"co2-emissions","en":"CO₂ emissions","cz":"emise CO₂","def":"Oxid uhličitý vypuštěný při výrobě elektřiny pro výpočty. Odhad: spotřeba energie krát emisní faktor elektřiny.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-3-1"},{"id":"community-and-support","en":"community and support","cz":"komunita a podpora","def":"Čtvrté kritérium výběru. Přednost mají modely s aktivní komunitou a podrobnou dokumentací, které usnadní nasazení a řešení problémů.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"community-of-practice","en":"community of practice","cz":"komunita praxe","def":"Interní skupina, která se pravidelně schází, ukazuje úspěšná použití GenAI, probírá potíže, zpřesňuje osvědčené postupy, sdílí knihovny vzorů promptů a dokumentuje poučení.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"compliance-and-regulatory-issues","en":"compliance and regulatory issues","cz":"problémy se souladem s předpisy a regulací","def":"Druhé riziko stínové AI. Neschválený nástroj může vést k porušení oborových norem a předpisů (3.4.1) a k právním následkům.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-1"},{"id":"compliance-risk","en":"compliance risk","cz":"riziko nesouladu s předpisy","def":"Riziko, že použití generativní AI v rozporu s předpisy o ochraně dat, například GDPR, povede k právním sporům.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-1"},{"id":"consistency-check","en":"consistency check","cz":"kontrola konzistence","def":"Ověření, že si vygenerované výstupy neprotiřečí navzájem ani se známými informacemi. Metoda detekce halucinací.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-1-2"},{"id":"constraints","en":"constraints","cz":"omezení","def":"Komponenta promptu s pravidly a omezeními, která určují, jak se instrukce použije na vstupní data (rozsah, technika, zákazy, priorita zdrojů).","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"context","en":"context","cz":"kontext","def":"Komponenta promptu s informacemi o pozadí: testovaný objekt, testovaná funkce, okolnosti. Pomáhá modelu určit testovací podmínky.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"context-manipulation","en":"context manipulation","cz":"manipulace s kontextem","def":"Vektor útoku: požadavky navržené tak, aby z modelu získaly důvěrná trénovací data. Příkladem je zahlcení kontextového okna dlouhými prompty.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"context-window","en":"context window","cz":"kontextové okno","def":"Množství textu měřené v tokenech, které model bere v úvahu při generování odpovědi. Co se do okna nevejde, model nevidí.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"core-prompting-techniques","en":"core prompting techniques","cz":"základní techniky promptování","def":"Tři techniky, které sylabus vybírá pro testování: prompt chaining, few-shot prompting a meta prompting.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-2"},{"id":"coverage-analysis","en":"coverage analysis","cz":"analýza pokrytí","def":"Mapování požadavků a uživatelských scénářů na testovací podmínky s cílem najít nepokryté části testovací báze.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-1"},{"id":"cross-verification","en":"cross-verification","cz":"křížové ověření","def":"Porovnání výstupu AI s existující dokumentací, požadavky a známým chováním systému. Metoda detekce halucinací, lze ji částečně automatizovat.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-1-2"},{"id":"data-anonymization","en":"data anonymization","cz":"anonymizace dat","def":"Nevratné odstranění vazby údajů na konkrétní osobu maskováním nebo nahrazením neidentifikujícími údaji.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"data-breach","en":"data breach","cz":"únik dat (narušení bezpečnosti dat)","def":"Situace, kdy se chráněná data dostanou k neoprávněné osobě nebo mimo prostředí, které je mělo chránit.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-1"},{"id":"data-exfiltration","en":"data exfiltration","cz":"vynesení dat","def":"Neoprávněné získání dat ze systému. V sylabu v1.0 název vektoru, který v1.1 přejmenovala na context manipulation.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"data-minimization","en":"data minimization","cz":"minimalizace dat","def":"Nezpracovávat citlivá data, pokud to zákon nedovoluje, a z necitlivých dat použít jen nezbytné množství.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"data-poisoning","en":"data poisoning","cz":"otrávení dat (data poisoning)","def":"Vektor útoku: manipulace s trénovacími daty. Příklad ze sylabu: falešná hodnocení výsledků AI generovaného reportu o testování.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"data-privacy","en":"data privacy","cz":"ochrana dat a soukromí","def":"Ochrana osobních údajů nebo jinak citlivých informací před nežádoucím prozrazením.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-2"},{"id":"data-quality","en":"data quality","cz":"kvalita dat","def":"Přesnost a relevance vstupních dat pro prompty, chráněných bezpečnostními postupy. Je podmínkou důvěryhodných výsledků LLM.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"data-sanitization","en":"data sanitization","cz":"sanitizace dat","def":"Odstranění nebo zamaskování citlivých, osobních a důvěrných informací dříve, než se data předají modelu.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-1"},{"id":"deep-learning","en":"deep learning","cz":"hluboké učení","def":"Strojové učení s neuronovými sítěmi o více vrstvách, které se samo učí příznaky z velkých a složitých dat, jako jsou obrázky, zvuk nebo text.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-1"},{"id":"discovery","en":"Discovery","cz":"objevování","def":"První fáze zavedení GenAI. Povědomí a budování schopností: školení týmů, zpřístupnění LLM/SLM a experimenty s prvními případy použití.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-4"},{"id":"diversity","en":"diversity","cz":"rozmanitost (diversity)","def":"Šíře pokrytých vstupů, chování uživatelů a okrajových případů bez zbytečného opakování.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"domain-expertise-consultation","en":"domain expertise consultation","cz":"konzultace s doménovým expertem","def":"Zapojení odborníka na danou oblast, který ověří přesnost vygenerovaného obsahu a zachytí jemné nepřesnosti. Metoda detekce halucinací.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-1-2"},{"id":"embedding","en":"embedding","cz":"embedding (vektorová reprezentace)","def":"Číselný vektor ve vícerozměrném prostoru, který reprezentuje token a zachycuje jeho význam, syntaxi a vztahy v kontextu. Podobné tokeny mají blízké vektory.","kap":[1,4],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"energy-consumption","en":"energy consumption","cz":"spotřeba energie","def":"Energie potřebná pro trénink a provoz modelů. Roste s používáním a závisí na složitosti úlohy a potřebných výpočetních zdrojích.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-3-1"},{"id":"eu-ai-act","en":"EU AI Act","cz":"akt o umělé inteligenci (EU AI Act)","def":"Předpis EU, který zavádí právní rámec pro rizika AI a dělí aplikace podle úrovně rizika. Vyžaduje transparentnost, odpovědnost a zmírnění zkreslení.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-4-1"},{"id":"execution-success-rate","en":"execution success rate","cz":"míra úspěšného spuštění","def":"Podíl vygenerovaných artefaktů, které lze v testovacím prostředí spustit bez úprav (bez syntaktických chyb a problémů s formátem).","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"fear-of-job-displacement","en":"fear of job displacement","cz":"strach ze ztráty práce","def":"Obava lidí, že je AI nahradí. Může zpomalit zavádění a zhoršit náladu v týmu, proto ji sylabus doporučuje řešit včas.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-4"},{"id":"feature","en":"feature","cz":"příznak","def":"Jedna měřitelná vlastnost vstupních dat, kterou algoritmus strojového učení používá při trénování a model při předpovědi.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-1"},{"id":"few-shot-prompting","en":"few-shot prompting","cz":"few-shot prompting","def":"Prompt s několika (víc než jedním) příklady vstupu a očekávaného výstupu. Příklady ukotví tvar a styl výsledku; hodí se pro opakující se úlohy s pevným formátem.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-2"},{"id":"fine-tuning","en":"fine-tuning","cz":"fine-tuning (doladění modelu)","def":"Učení s učitelem na datové sadě označených příkladů, které upraví váhy předtrénovaného LLM nebo SLM a přizpůsobí ho konkrétní úloze nebo doméně.","kap":[4],"klicove":true,"href":"kapitola-4/vyklad.html#oddil-4-2-1"},{"id":"fine-tuning-potential","en":"fine-tuning potential","cz":"potenciál pro doladění","def":"Druhé kritérium výběru. Posouzení, jestli je možné a užitečné model doladit na doménových datech pro vyšší přesnost a relevanci.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"foundation-llm","en":"foundation LLM","cz":"základní (foundation) LLM","def":"Univerzální model předtrénovaný na velkém a pestrém množství dat, který umí předpovídat další token. Pro konkrétní úlohu ho je obvykle nutné dál přizpůsobit.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-3"},{"id":"front-end","en":"front-end","cz":"front-end (uživatelské rozhraní)","def":"Část infrastruktury, kde tester zadává dotazy nebo příkazy a kde se zobrazuje výsledek.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"functional-capabilities","en":"functional capabilities","cz":"funkční schopnosti (modelu)","def":"Co model umí, například zpracovat multimodální vstup nebo uvažovat ve více krocích.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"genai-strategy-for-software-testing","en":"GenAI strategy (for software testing)","cz":"strategie generativní AI pro testování","def":"Dokument nebo rozhodnutí, které určuje cíle použití GenAI v testování, výběr modelů, práci s daty, školení, metriky a pravidla. Je podkladem pro roadmapu.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"genai-powered-test-agent","en":"GenAI-powered test agent","cz":"testovací agent poháněný GenAI","def":"AI agent, který samostatně nebo polosamostatně vykonává testovací úlohy. Test manažer ho koordinuje spolu s lidmi.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"general-data-protection-regulation-gdpr","en":"General Data Protection Regulation (GDPR)","cz":"obecné nařízení o ochraně osobních údajů (GDPR)","def":"Nařízení (EU) 2016/679. Použití generativní AI výslovně nezakazuje, ale omezuje zpracování osobních údajů, hlavně zákonností a omezením účelu.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"generation","en":"generation","cz":"generování","def":"Druhý krok zpracování dotazu v RAG. LLM dostane nalezené části jako kontext a vytvoří odpověď, která spojuje jeho znalosti s dodanými daty.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"generative-ai-genai","en":"generative AI (GenAI)","cz":"generativní AI","def":"Oblast AI, která pomocí modelů strojového učení vytváří nový obsah (text, obrázky, kód) podobný obsahu vytvořenému člověkem.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-1"},{"id":"generative-pre-trained-transformer-gpt","en":"generative pre-trained transformer (GPT)","cz":"GPT","def":"Model hlubokého učení s architekturou transformer, předtrénovaný na velkém množství textu, aby rozuměl textu a vytvářel text podobný lidskému.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"gherkin","en":"Gherkin","cz":"Gherkin","def":"Strukturovaný jazyk pro popis scénářů chování s klíčovými slovy Feature, Scenario, Given, When, Then. Typický cíl few-shot promptu.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"goal-driven-agent-based-test-automation","en":"goal-driven, agent-based test automation","cz":"automatizace testování řízená cílem a postavená na agentech","def":"Automatizace, kde agent dostane cíl a kroky si odvodí sám, na rozdíl od skriptu, který kroky přesně předepisuje.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"grounded-response","en":"grounded response","cz":"podložená odpověď","def":"Odpověď modelu, která vychází z relevantních a přesných informací získaných při vyhledávání, a ne jen ze znalostí z trénování.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"guided-exercises","en":"guided exercises","cz":"řízená cvičení","def":"Cvičení s jasným zadáním a zpětnou vazbou, součást praktického školení.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"hallucination","en":"hallucination","cz":"halucinace","def":"Výstup LLM, který je fakticky nesprávný nebo nesouvisí se zadanou úlohou. V testování například smyšlené testovací případy, nefunkční skripty nebo testy na neexistující akceptační kritéria.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-1-1"},{"id":"hands-on-approach","en":"hands-on approach","cz":"praktický přístup","def":"Princip budování schopností týmu: učit se prací s různými modely na reálných testovacích úlohách, ne jen teorií.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"human-in-the-loop","en":"human-in-the-loop","cz":"člověk ve smyčce","def":"Uspořádání, kdy agent v určených bodech čeká na schválení nebo kontrolu člověka, typicky před akcí s vedlejším efektem.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"hybrid-team","en":"hybrid team","cz":"hybridní tým","def":"Tým složený z lidí a nástrojů nebo agentů GenAI. Jeho řízení vyžaduje nové manažerské dovednosti.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-3"},{"id":"hyperparameter","en":"hyperparameter","cz":"hyperparametr","def":"Nastavení, které ovlivňuje trénování nebo generování modelu a nenaučí se z dat, například teplota při generování odpovědi.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"image-captioning","en":"image captioning","cz":"popis obrázku","def":"Úloha, při které model vytvoří textový popis toho, co je na obrázku.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-4"},{"id":"impact-analysis","en":"impact analysis","cz":"analýza dopadu","def":"Určení částí softwaru, které může změna ovlivnit. GenAI ji umí udělat z analýzy změn v kódu a zacílit regresní testy.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"in-house-development","en":"in-house development","cz":"vlastní vývoj","def":"Přístup, kdy organizace sama vyvíjí testovací nástroj s generativní AI. Dává nejvíc kontroly, ale vyžaduje plánování zdrojů, procesy validace a údržby a odbornost.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-2-2"},{"id":"inference","en":"inference","cz":"inference","def":"Použití natrénovaného modelu na nový vstup. U LLM znamená postupnou předpověď dalšího tokenu, dokud není odpověď hotová.","kap":[1,3,4],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"information-security-and-data-privacy-weaknesses","en":"information security and data privacy weaknesses","cz":"slabiny v informační bezpečnosti a ochraně dat","def":"První riziko stínové AI. Osobní AI nástroje nemusí mít dostatečné zabezpečení, a tak hrozí únik dat.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-1"},{"id":"initiation-and-usage-definition","en":"Initiation and usage definition","cz":"zahájení a definice použití","def":"Druhá fáze zavedení GenAI. Identifikace a prioritizace praktických případů použití, posouzení testovací infrastruktury s LLM, rozvoj odbornosti a sladění s potřebami organizace.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-4"},{"id":"input-data","en":"input data","cz":"vstupní data","def":"Komponenta promptu s materiálem potřebným k úloze: uživatelské scénáře, akceptační kritéria, snímky, kód, existující testy, ukázky výstupu, logy.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"instruction","en":"instruction","cz":"instrukce","def":"Komponenta promptu se samotnou úlohou: jasně, v rozkazovacím způsobu, stručně, s podstatnými požadavky.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"instruction-tuned-llm","en":"instruction-tuned LLM","cz":"LLM vyladěný na instrukce","def":"Základní LLM doladěný na dvojicích prompt a očekávaná odpověď, aby spolehlivě plnil pokyny a držel zadaný formát. Často posílený zpětnou vazbou.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-3"},{"id":"integrate-user-feedback","en":"integrate user feedback","cz":"zapracování zpětné vazby uživatelů","def":"Sběr názorů testerů a dalších čtenářů na užitečnost, srozumitelnost a podrobnost výstupu a úprava promptu podle nich.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-2"},{"id":"iso-iec-23053-2022","en":"ISO/IEC 23053:2022","cz":"ISO/IEC 23053:2022","def":"Standard s rámcem pro AI systémy se strojovým učením a jejich životní cyklus. Zdůrazňuje bezpečnost a transparentnost, v testování kvalitu dat.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-4-1"},{"id":"iso-iec-42001-2023","en":"ISO/IEC 42001:2023","cz":"ISO/IEC 42001:2023","def":"Standard s požadavky na systém řízení AI v organizaci. V testování podporuje doporučené postupy, konzistenci a spolehlivost.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-4-1"},{"id":"iterative-prompt-modification","en":"iterative prompt modification","cz":"iterativní úprava promptu","def":"Postupné vylepšování základního promptu podle skutečných výsledků: doplnění kontextu, úprava formulací a terminologie.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-2"},{"id":"jailbreak","en":"jailbreak","cz":"jailbreak","def":"Prompt, který má model přimět obejít jeho vlastní ochranná pravidla.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"keyword-driven-testing","en":"keyword-driven testing","cz":"testování řízené klíčovými slovy","def":"Skriptovací technika, kde testovací skripty obsahují klíčová slova a jejich implementace je v knihovně. Pro generování skriptů se hodí few-shot.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"known-anomalies-list","en":"known anomalies list","cz":"seznam známých anomálií","def":"Udržovaný seznam již známých problémů, se kterým se při analýze regresního reportu porovnávají nová selhání (HO-2.2.3b).","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"lack-of-control-over-data-usage","en":"lack of control over data usage","cz":"ztráta kontroly nad použitím dat","def":"Riziko pro ochranu dat: nástroj generativní AI ukládá a zpracovává citlivá data bez výslovného souhlasu nebo kontroly uživatele.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-1"},{"id":"large-language-model-llm","en":"large language model (LLM)","cz":"velký jazykový model (LLM)","def":"Model generativní AI předtrénovaný na velmi velkém množství textu, který rozumí přirozenému jazyku a vytváří text podobný lidskému.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1"},{"id":"large-language-model-operations-llmops","en":"Large Language Model Operations (LLMOps)","cz":"LLMOps","def":"Praktiky, nástroje a procesy pro vývoj, nasazení, monitoring a údržbu LLM v produkčním prostředí.","kap":[4],"klicove":true,"href":"kapitola-4/vyklad.html#oddil-4-2-2"},{"id":"lessons-learned","en":"lessons learned","cz":"poučení (z projektů)","def":"Zapsané zkušenosti z nasazení GenAI napříč projekty a doménami, které komunita praxe sdílí.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"licensing-type-commercial-vs-open-source","en":"licensing type (commercial vs. open source)","cz":"typ licence (komerční a open source)","def":"Podmínky, za kterých lze model používat. Komerční model se platí podle licence nebo spotřeby, open source model má otevřenou licenci, ale vlastní provozní náklady.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"llm-as-a-service","en":"LLM-as-a-Service","cz":"LLM jako služba","def":"Model provozovaný poskytovatelem a dostupný přes API nebo webové rozhraní.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-2-2"},{"id":"llm-powered-agent","en":"LLM-powered agent","cz":"agent postavený na LLM","def":"Aplikace, která spojuje uvažování, rozhodování a paměť LLM a pomocí nástrojů provádí úlohy. Pracuje autonomně nebo poloautonomně.","kap":[4],"klicove":true,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"llm-powered-test-infrastructure","en":"LLM-powered test infrastructure","cz":"testovací infrastruktura postavená na LLM","def":"Nástroje a prostředí pro testování, které využívají LLM. Mohou být cílem útoků, například úniku dat nebo neoprávněného přístupu.","kap":[3,4],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-1"},{"id":"llm-powered-test-tool","en":"LLM-powered test tool","cz":"testovací nástroj postavený na LLM","def":"Nástroj, který volá LLM přes API a provádí předem dané, často automatizované testovací úlohy.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1"},{"id":"llm-powered-testing-application","en":"LLM-powered testing application","cz":"testovací nástroj postavený na LLM","def":"Aplikace, která integruje LLM přes API a plní přesně vymezené, často automatizované testovací úlohy uvnitř testovacího nástroje nebo frameworku.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-2-2"},{"id":"logical-validation","en":"logical validation","cz":"logická validace","def":"Posouzení logického toku vygenerovaného obsahu (konzistence, soudržnost, navazující kroky) v revizních cyklech. Metoda detekce chyb v uvažování.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-1-2"},{"id":"machine-learning-ml","en":"machine learning (ML)","cz":"strojové učení","def":"Proces, při kterém se systém učí z dat nebo ze zkušenosti, místo aby dostal pevně napsaná pravidla.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-1"},{"id":"malicious-code-generation","en":"malicious code generation","cz":"generování škodlivého kódu","def":"Vektor útoku: model je zmanipulován, aby při použití generoval kód se zadními vrátky, například volání externích příkazů nebo spojení na škodlivou IP adresu.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"measurable-test-objectives","en":"measurable test objectives","cz":"měřitelné cíle testování","def":"Cíle pro použití GenAI, které lze vyhodnotit, například vyšší produktivita testování, kratší testovací cykly nebo vyšší kvalita testování.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"memory-agent","en":"memory (agent)","cz":"paměť agenta","def":"Informace, které agent uchovává. Krátkodobá paměť je kontext jednoho běhu, dlouhodobá přežije konec běhu, například v souborech nebo databázi.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"meta-prompting","en":"meta prompting","cz":"meta prompting","def":"Technika, při které LLM vytváří nebo vylepšuje prompt a tester ho v opakovaném cyklu posuzuje a upravuje. Je to forma párové práce testera s AI.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-2"},{"id":"modality","en":"modality","cz":"modalita","def":"Druh dat, se kterým model pracuje, například text, obraz, zvuk nebo video.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-4"},{"id":"model-performance","en":"model performance","cz":"výkon modelu","def":"První kritérium výběru. Kvalita výsledků modelu na cílových testovacích úlohách měřená proti benchmarkům organizace metrikami z 2.3.1.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"multi-agent-architecture","en":"multi-agent architecture","cz":"multiagentní architektura","def":"Systém, kde spolupracuje více agentů se specializovanými rolemi a společně řeší složité úlohy efektivněji než jeden agent.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"multimodal-model","en":"multimodal model","cz":"multimodální model","def":"Model generativní AI, který zpracovává a vytváří obsah ve více druzích dat (modalitách), například v textu, obrazech, zvuku nebo videu.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-4"},{"id":"multimodal-prompt","en":"multimodal prompt","cz":"multimodální prompt","def":"Prompt, který kombinuje víc druhů vstupu, například text a obrázek (wireframe GUI).","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-1"},{"id":"natural-language-processing-nlp","en":"natural language processing (NLP)","cz":"zpracování přirozeného jazyka","def":"Počítačové zpracování textu v přirozeném jazyce za účelem získání informací a reprezentace znalostí.","kap":[1,2],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-3"},{"id":"neural-network","en":"neural network","cz":"neuronová síť","def":"Struktura strojového učení složená z vrstev propojených výpočetních jednotek, jejichž váhy se nastaví při trénování.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-1"},{"id":"nist-ai-risk-management-framework-ai-rmf","en":"NIST AI Risk Management Framework (AI RMF)","cz":"rámec NIST pro řízení rizik AI","def":"Americký rámec doporučení pro řízení rizik AI se zaměřením na férovost, transparentnost a bezpečnost. V testování pomáhá předcházet zkresleným výsledkům.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-4-1"},{"id":"non-deterministic-behaviour","en":"non-deterministic behaviour","cz":"nedeterministické chování","def":"Vlastnost LLM, kvůli které stejný vstup může vést k různým výstupům. Příčinou je pravděpodobnostní inference a nastavení hyperparametrů.","kap":[1,3],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"one-shot-prompting","en":"one-shot prompting","cz":"one-shot prompting","def":"Prompt s právě jedním příkladem, který ukazuje očekávaný výstup pro daný vstup.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-2"},{"id":"opacity","en":"opacity","cz":"neprůhlednost","def":"Chybějící vhled do toho, jak LLM dospívá ke svým rozhodnutím a výstupům. Ztěžuje ladění a validaci doladěného modelu.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-2-1"},{"id":"operational-parameters","en":"operational parameters","cz":"provozní parametry","def":"Část systémového promptu, která určuje, jak model odpovídá: tón, stručnost, pravidla domény, zakázané chování.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-3"},{"id":"orchestration","en":"orchestration","cz":"orchestrace","def":"Koordinovaná spolupráce více agentů se specializovanými rolemi.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"output-analysis","en":"output analysis","cz":"analýza výstupu","def":"Zkoumání výstupu AI kvůli nepřesnostem a nekonzistencím (např. vůči testovací bázi), aby šlo prompt upravit a chyby se neopakovaly.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-2"},{"id":"output-format","en":"output format","cz":"formát výstupu","def":"Komponenta promptu, která určuje podobu, strukturu a vlastnosti odpovědi: tabulka, sloupce, JSON, Gherkin, délka.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"output-testing","en":"output testing","cz":"testování výstupu","def":"Spuštění vygenerovaných testovacích případů nebo skriptů proti testovanému objektu a ověření výsledků. Metoda detekce chyb v uvažování.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-1-2"},{"id":"overfitting","en":"overfitting","cz":"přeučení","def":"Stav, kdy je model příliš přizpůsobený trénovacím datům a na nových, neviděných datech dává horší výsledky.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-2-1"},{"id":"pairing-with-genai","en":"pairing (with GenAI)","cz":"párová práce s GenAI","def":"Interaktivní spolupráce testera a AI na společném cíli, podobná párovému programování nebo testování. Sylabus ji uvádí u meta promptingu.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-2"},{"id":"parameter","en":"parameter","cz":"parametr (modelu)","def":"Vnitřní číselná váha modelu, kterou model získal při trénování. Počet parametrů vyjadřuje velikost modelu.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"peer-learning","en":"peer learning","cz":"učení od kolegů","def":"Sdílení zkušeností mezi členy týmu, například vzájemná kontrola promptů a ukázky toho, co funguje.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"personally-identifiable-information-pii","en":"personally identifiable information (PII)","cz":"osobní identifikační údaje","def":"Údaje, podle kterých lze přímo nebo nepřímo určit konkrétní osobu, například jméno, rodné číslo nebo číslo účtu.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-1"},{"id":"post-processing","en":"post-processing","cz":"následné zpracování výstupu","def":"Úprava surového výstupu LLM v back-endu, aby odpovídal testovacím podmínkám testovacího procesu, než se zobrazí uživateli.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"precision","en":"precision","cz":"přesnost (precision)","def":"Správnost výstupu vzhledem ke konkrétnímu cíli. Příklad: do jaké míry vygenerované testy správně identifikují anomálie.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"preprocessing","en":"preprocessing","cz":"předzpracování","def":"První fáze RAG, která proběhne předem: rozdělení dokumentů, vyčištění, převod na embeddingy a uložení do vektorové databáze.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"privacy-preserving-prompt-engineering","en":"privacy-preserving prompt engineering","cz":"tvorba promptů šetrná k soukromí","def":"Psaní promptů tak, aby neobsahovaly zbytečné osobní nebo důvěrné údaje.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-1"},{"id":"process-guidelines","en":"process guidelines","cz":"procesní pravidla","def":"Pravidla pro používání GenAI, která zajišťují soulad s předpisy a etikou: pravidla pro citlivá data, povinnosti transparentnosti a quality gates s revizí testwaru.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"prompt","en":"prompt","cz":"prompt","def":"Vstup, kterým se LLM zadává úloha: pokyn a podle potřeby kontext, data, příklady a požadavky na tvar odpovědi.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1"},{"id":"prompt-chaining","en":"prompt chaining","cz":"řetězení promptů","def":"Rozklad úlohy na posloupnost dílčích promptů. Výstup každého kroku se ručně nebo automaticky zkontroluje a upraví, než slouží jako vstup dalšího kroku.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-2"},{"id":"prompt-engineering","en":"prompt engineering","cz":"prompt engineering (tvorba promptů)","def":"Návrh, zkoušení a postupné vylepšování promptů, aby LLM vracel přesné, relevantní a konzistentní výstupy.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1"},{"id":"prompt-injection","en":"prompt injection","cz":"prompt injection","def":"Útok, při kterém útočník vloží do vstupu modelu text, který model vyloží jako instrukci. Nepřímá varianta schová instrukci do dokumentu nebo obrázku.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"prompt-library","en":"prompt library","cz":"knihovna promptů","def":"Sdílená sbírka ověřených promptů pro opakované testovací úlohy. Podporuje standardizaci a učení v týmu.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-2"},{"id":"prompt-pattern","en":"prompt pattern","cz":"vzor promptu","def":"Znovupoužitelná šablona pro tvorbu účinných promptů, která vede GenAI ke konzistentním a spolehlivým výstupům.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"prompt-pattern-library","en":"prompt pattern library","cz":"knihovna vzorů promptů","def":"Sdílená sbírka osvědčených vzorů promptů, kterou udržuje tým nebo komunita praxe.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"prompt-preparation","en":"prompt preparation","cz":"příprava promptu","def":"Složení promptu pro LLM z instrukcí, dotazu uživatele a dat nalezených v databázích. Dělá ji back-end.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"prompt-refinement","en":"prompt refinement","cz":"zpřesňování promptů","def":"Postupné ladění zadání pro model, dokud výstup nesplní požadavky.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-1"},{"id":"pseudonymization","en":"pseudonymization","cz":"pseudonymizace","def":"Nahrazení identifikujících údajů zástupnými identifikátory. Vazbu na osobu lze obnovit pomocí odděleně uložených informací.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"quality-gate","en":"quality gate","cz":"kvalitativní brána","def":"Kontrolní bod, přes který výstup projde jen po splnění kritérií. V 5.1.2 jde o povinnou revizi testwaru vygenerovaného AI.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"random-seed","en":"random seed","cz":"náhodné semínko (seed)","def":"Počáteční hodnota generátoru pseudonáhodných čísel. Když ji implementace dovolí nastavit, použije se stejná pseudonáhodná posloupnost a výstup je lépe opakovatelný.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-1-4"},{"id":"reasoning-error","en":"reasoning error","cz":"chyba v uvažování","def":"Model špatně vyloží logickou strukturu úlohy (příčinu a následek, podmínku, postup po krocích) a dojde k chybnému závěru. Vzniká, protože LLM rozpoznává vzory místo logického odvozování.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-1-1"},{"id":"reasoning-llm","en":"reasoning LLM","cz":"uvažující (reasoning) LLM","def":"LLM, který staví na modelu vyladěném na instrukce a je dál trénován na logické vyvozování a řešení problémů o více krocích.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-3"},{"id":"recall","en":"recall","cz":"úplnost (recall)","def":"Schopnost modelu zachytit všechny relevantní případy. Příklad: pokrytí platných i neplatných tříd ekvivalence.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"recurring-cost","en":"recurring cost","cz":"opakované náklady","def":"Třetí kritérium výběru. Náklady, které se opakují po celou dobu používání modelu: licenční poplatky a provozní náklady včetně výpočetního výkonu.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"regression-testing","en":"regression testing","cz":"regresní testování","def":"Testování, které ověřuje, že změna nezpůsobila nežádoucí dopady v dříve fungujících částech. Kvůli růstu sady vhodné k automatizaci v CI/CD.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"relational-database","en":"relational database","cz":"relační databáze","def":"Databáze se strukturovanými daty v tabulkách. V infrastruktuře s LLM drží například testovací případy, defekty nebo výsledky běhů.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"relevance-and-contextual-fit","en":"relevance and contextual fit","cz":"relevance a soulad s kontextem","def":"Zda je výstup použitelný a vhodný pro daný kontext: soulad s testovací bází a doménovými požadavky.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"request-manipulation","en":"request manipulation","cz":"manipulace s požadavkem","def":"Vektor útoku: vložení dat, která naruší výstup modelu. Příklad ze sylabu: obrázek zavede model do jiného kontextu a vyvolá halucinace v akceptačních kritériích.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-2"},{"id":"resources-training","en":"resources training","cz":"školení lidí","def":"Školicí programy a pravidla, která zajistí odpovědné a etické používání nástrojů generativní AI.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"retrieval","en":"retrieval","cz":"vyhledání","def":"První krok zpracování dotazu v RAG. Dotaz se převede na embedding a ve vektorové databázi se najdou části s největší sémantickou podobností.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"retrieval-augmented-generation-rag","en":"retrieval-augmented generation (RAG)","cz":"RAG – generování rozšířené o vyhledávání","def":"Technika, která spojuje LLM s vyhledávačem. Vyhledávač najde k dotazu relevantní data a model z nich vygeneruje přesnější odpověď odpovídající kontextu.","kap":[4],"klicove":true,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"right-sized-model","en":"right-sized model","cz":"model přiměřené velikosti","def":"Model, jehož schopnosti a výpočetní náročnost odpovídají úloze. Snižuje náklady i spotřebu energie.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-1"},{"id":"roadmap","en":"roadmap","cz":"plán zavedení (roadmapa)","def":"Časový plán kroků, kterými organizace podle strategie zavádí GenAI do testovacích procesů a sleduje postup.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1"},{"id":"role","en":"role","cz":"role","def":"Komponenta promptu, která určuje perspektivu nebo personu modelu (tester, test manažer, inženýr automatizace) a tím odpovědnost, tón a přístup.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"root-cause-analysis","en":"root cause analysis","cz":"analýza kořenové příčiny","def":"Hledání skutečné příčiny selhání. GenAI ji podporuje sestavením reportu o defektu s logy, snímky a údaji o prostředí.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"rule-based-chatbot","en":"rule-based chatbot","cz":"chatbot založený na pravidlech","def":"Chatbot, který odpovídá předem napsanými odpověďmi podle pravidel. Sylabus ho staví do protikladu k infrastruktuře s LLM, která odpovědi tvoří dynamicky z kontextu.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-1"},{"id":"scalability","en":"scalability","cz":"škálovatelnost","def":"Schopnost řešení zvládnout rostoucí objem práce, počet uživatelů nebo projektů bez zásadní přestavby.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"secure-operational-environment","en":"secure operational environment","cz":"bezpečné provozní prostředí","def":"Prostředí pro LLM zvolené podle požadované důvěrnosti: komerční zabezpečená nabídka poskytovatele, zabezpečený cloud, nebo instalace ve vlastní infrastruktuře.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"security","en":"security","cz":"bezpečnost","def":"Míra, do jaké komponenta nebo systém chrání svá data a zdroje před neoprávněným přístupem nebo použitím a zajišťuje přístup oprávněným uživatelům.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-2"},{"id":"security-audit","en":"security audit","cz":"bezpečnostní audit","def":"Audit, který hodnotí bezpečnostní procesy a infrastrukturu organizace. U generativní AI se má provádět pravidelně spolu s hodnocením zranitelností.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-3"},{"id":"self-attention","en":"self-attention","cz":"self-attention (sebepozornost)","def":"Mechanismus transformeru, který pro každý token určí, jak silně souvisí s ostatními tokeny ve vstupu.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"self-healing-test","en":"self-healing test","cz":"samoopravný test","def":"Automatizovaný test, jehož skript se při drobné změně UI nebo API automaticky přizpůsobí, aby zbytečně nepadal.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"semantic-similarity","en":"semantic similarity","cz":"sémantická podobnost","def":"Podobnost textů podle významu, měřená jako blízkost jejich embeddingů. RAG podle ní vybírá části dokumentů.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"semi-autonomous-agent","en":"semi-autonomous agent","cz":"poloautonomní agent","def":"Agent, který pracuje s pravidelným dohledem člověka, aby výstup odpovídal cílům uživatele.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"shadow-ai","en":"shadow AI","cz":"stínová AI","def":"Používání nástrojů nebo systémů generativní AI v organizaci bez formálního schválení nebo dohledu. Typicky osobní účet ve veřejném chatbotu, do kterého se vkládají pracovní podklady.","kap":[5],"klicove":true,"href":"kapitola-5/vyklad.html#oddil-5-1-1"},{"id":"small-language-model-slm","en":"small language model (SLM)","cz":"malý jazykový model (SLM)","def":"Kompaktní jazykový model s výrazně menším počtem parametrů než LLM, navržený jako lehké a zaměřené řešení.","kap":[1,4,5],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"structured-learning-path","en":"structured learning path","cz":"strukturovaná vzdělávací cesta","def":"Naplánovaný postup učení od základní tvorby promptů k technikám specifickým pro testování.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-2"},{"id":"structured-prompt","en":"structured prompt","cz":"strukturovaný prompt","def":"Prompt složený ze šesti komponent: role, context, instruction, input data, constraints, output format.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-1-1"},{"id":"symbolic-ai","en":"symbolic AI","cz":"symbolická AI","def":"Přístup k AI, který napodobuje lidské rozhodování pomocí symbolů a logických pravidel zapsaných člověkem. Z dat se neučí.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-1"},{"id":"synthetic-test-data","en":"synthetic test data","cz":"syntetická testovací data","def":"Vygenerovaná data, která připomínají produkční, pokrývají i extrémní situace a neobsahují skutečné citlivé údaje.","kap":[2,3],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"system-prompt","en":"system prompt","cz":"systémový prompt","def":"Pokyny, které nastavuje vývojář nebo tester nástroje. Platí po celou konverzaci, určují roli, chování, provozní parametry a omezení a uživatel je obvykle nevidí.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-3"},{"id":"task-specific-metrics","en":"task-specific metrics","cz":"metriky specifické pro úlohu","def":"Metriky přizpůsobené konkrétní testovací činnosti, které doplňují sedm obecných metrik.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"technical-features","en":"technical features","cz":"technické vlastnosti (modelu)","def":"Technické parametry modelu, například velikost kontextového okna.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-3"},{"id":"temperature","en":"temperature","cz":"teplota (temperature)","def":"Parametr, který řídí náhodnost a kreativitu výstupu LLM. Nižší teplota zužuje rozdělení pravděpodobností, výstup je konzistentnější, ale méně rozmanitý.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-1-4"},{"id":"test-analysis","en":"test analysis","cz":"testovací analýza","def":"Činnost, ve které se analyzuje testovací báze a určují a prioritizují testovací podmínky. Odpovídá na otázku co testovat.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-1"},{"id":"test-basis","en":"test basis","cz":"testovací báze","def":"Podklady, ze kterých se odvozují testy: požadavky, uživatelské scénáře, specifikace, wireframy.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-1"},{"id":"test-case","en":"test case","cz":"testovací případ","def":"Sada předpokladů, vstupů, akcí, očekávaných výsledků a následných podmínek vytvořená z testovacích podmínek. GenAI vytváří jejich návrhy, které musí tester zkontrolovat.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"test-completion-report","en":"test completion report","cz":"souhrnný report z testování","def":"Report na konci testovací činnosti s výsledky, úspěchy a poučením. GenAI ho pomáhá sestavit.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-4"},{"id":"test-condition","en":"test condition","cz":"testovací podmínka","def":"Testovatelný aspekt komponenty nebo systému, který je cílem testování. Vzniká v testovací analýze; GenAI ji umí odvodit z požadavků díky NLP.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-1"},{"id":"test-control","en":"test control","cz":"řízení testování","def":"Opatření přijatá na základě monitoringu: změna priorit, harmonogramu nebo zdrojů. GenAI k nim dává podklady.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-4"},{"id":"test-data","en":"test data","cz":"testovací data","def":"Data potřebná k provedení testů. GenAI umí vytvořit syntetická data podobná produkčním, včetně extrémních hodnot, bez skutečných osobních údajů.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"test-design","en":"test design","cz":"návrh testů","def":"Činnost, ve které se testovací podmínky rozpracují do testovacích případů a dalšího testwaru. Odpovídá na otázku jak testovat.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"test-execution-schedule","en":"test execution schedule","cz":"harmonogram provedení testů","def":"Pořadí a časový plán spouštění testů. GenAI ho umí navrhnout podle závislostí, priorit, rizik a zdrojů.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"test-implementation","en":"test implementation","cz":"implementace testování","def":"Činnost, ve které se vytvoří nebo získá testware potřebný k provedení testů: procedury, skripty, data, harmonogram provedení.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"test-infrastructure","en":"test infrastructure","cz":"infrastruktura testování","def":"Testovací prostředí, testovací nástroje, vybavení pracoviště a procedury potřebné k provádění testování (slovník ISTQB). V kapitole 4 jde o infrastrukturu, která do testování zapojuje LLM.","kap":[4],"klicove":true,"href":"kapitola-4/vyklad.html#oddil-4-1"},{"id":"test-infrastructure-compatibility","en":"test infrastructure compatibility","cz":"kompatibilita s testovací infrastrukturou","def":"Požadavek, aby vybraný model šel napojit na stávající testovací prostředí a nástroje.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"test-monitoring","en":"test monitoring","cz":"monitoring testování","def":"Průběžné sledování testovacích činností a porovnávání postupu s plánem pomocí metrik. GenAI pomáhá s analýzou dat a trendů.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-2-4"},{"id":"test-oracle","en":"test oracle","cz":"testovací orákulum","def":"Zdroj, podle kterého tester určí očekávaný výsledek testu. LLM může očekávané výsledky navrhnout, ale je nutné je ověřit.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-2-1"},{"id":"test-report","en":"test report","cz":"report z testování","def":"Přehled výsledků a hodnocení testování, například report o postupu prací při testování nebo souhrnný report z testování. GenAI ho umí sestavit i analyzovat.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-3"},{"id":"test-review-methods","en":"test review methods","cz":"metody revize testů","def":"Postupy, jak zkontrolovat testware vygenerovaný AI, například kontrolní seznam nebo porovnání s referencí.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-2-1"},{"id":"test-script","en":"test script","cz":"testovací skript","def":"Posloupnost instrukcí pro provedení testu, obvykle automatizovaná. GenAI ji umí vytvořit ze strukturovaného testovacího případu pro různé frameworky.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-2-2"},{"id":"time-efficiency","en":"time efficiency","cz":"časová efektivita","def":"Ušetřený čas ve srovnání s ruční prací na stejném výsledku.","kap":[2],"klicove":false,"href":"kapitola-2/vyklad.html#oddil-2-3-1"},{"id":"token","en":"token","cz":"token","def":"Jednotka textu, se kterou model pracuje. Může to být znak, část slova nebo celé slovo. V tokenech se měří kontextové okno i cena za použití modelu.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"tokenization","en":"tokenization","cz":"tokenizace","def":"Rozdělení textu na menší jednotky (tokeny), se kterými jazykový model pracuje.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"tool","en":"tool","cz":"nástroj (u agenta)","def":"Předem definovaná funkce, kterou agent může zavolat, aby pracoval s externím systémem, například čtení souboru, volání API nebo vytvoření defektu.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-1-3"},{"id":"training-dataset","en":"training dataset","cz":"trénovací datová sada","def":"Soubor označených příkladů, na kterých se model dolaďuje, například dvojice uživatelský scénář a testovací případ.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-2-1"},{"id":"training-programs","en":"training programs","cz":"vzdělávací programy","def":"Školení, díky kterým tým získá technické i etické dovednosti pro efektivní používání nástrojů GenAI.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"transformer","en":"transformer","cz":"transformer","def":"Architektura modelu hlubokého učení, která pomocí mechanismu self-attention zachycuje vztahy mezi tokeny i ve vzdálených částech vstupu.","kap":[1],"klicove":true,"href":"kapitola-1/vyklad.html#oddil-1-1-2"},{"id":"transparency-obligation","en":"transparency obligation","cz":"povinnost transparentnosti","def":"Pravidlo, že se u výstupu uvádí, co vzniklo pomocí GenAI.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-2"},{"id":"unintentional-data-exposure","en":"unintentional data exposure","cz":"neúmyslné vyzrazení dat","def":"Riziko pro ochranu dat: model vytvoří výstup, který nechtěně odhalí citlivou informaci.","kap":[3],"klicove":false,"href":"kapitola-3/vyklad.html#oddil-3-2-1"},{"id":"use-case","en":"use case","cz":"případ použití","def":"Konkrétní úloha, pro kterou se GenAI v testování používá, například analýza reportů z testování nebo automatizace testů. Každý případ použití může být v jiné fázi zavedení.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-4"},{"id":"user-prompt","en":"user prompt","cz":"uživatelský prompt","def":"Konkrétní dotaz nebo úloha uživatele v dané interakci. Mění se s každou zprávou, je viditelný a tvoří bezprostřední kontext odpovědi.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-3"},{"id":"utilization-and-iteration","en":"Utilization and iteration","cz":"využívání a iterace","def":"Třetí, pokročilá fáze zavedení GenAI. Plná integrace do testovacích procesů, průběžný monitoring, měření a řízení transformace pro udržitelné přínosy a škálovatelnost.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-4"},{"id":"vague-intellectual-property","en":"vague intellectual property","cz":"nejasné duševní vlastnictví","def":"Třetí riziko stínové AI. Nástroje s nejasnými licenčními podmínkami mohou vést ke sporům o duševní vlastnictví, zvlášť při zpracování chráněných dat bez oprávnění.","kap":[5],"klicove":false,"href":"kapitola-5/vyklad.html#oddil-5-1-1"},{"id":"vector-database","en":"vector database","cz":"vektorová databáze","def":"Databáze optimalizovaná pro ukládání a dotazování vektorových reprezentací dat o mnoha rozměrech. V RAG v ní leží embeddingy částí dokumentů.","kap":[4],"klicove":true,"href":"kapitola-4/vyklad.html#oddil-4-1-2"},{"id":"vendor-assurances","en":"vendor assurances","cz":"záruky dodavatele","def":"Smluvní a technické záruky poskytovatele, například kde zpracovává data, jestli je používá k tréninku a jaký výkon garantuje.","kap":[4],"klicove":false,"href":"kapitola-4/vyklad.html#oddil-4-2-2"},{"id":"vision-language-model-vlm","en":"vision-language model (VLM)","cz":"model pro obraz a jazyk","def":"Podmnožina multimodálních modelů, která společně zpracovává obraz a text, například při popisu obrázku nebo odpovídání na otázky k obrázku.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-4"},{"id":"visual-question-answering","en":"visual question answering","cz":"odpovídání na otázky k obrázku","def":"Úloha, při které model odpovídá na dotaz k obsahu obrázku, například zda je na snímku obrazovky chybová hláška.","kap":[1],"klicove":false,"href":"kapitola-1/vyklad.html#oddil-1-1-4"},{"id":"vulnerability","en":"vulnerability","cz":"zranitelnost","def":"Slabina v komponentě, systému, postupech nebo kontrolách, kterou lze zneužít k úspěšnému bezpečnostnímu útoku.","kap":[3],"klicove":true,"href":"kapitola-3/vyklad.html#oddil-3-2"},{"id":"zero-shot-prompting","en":"zero-shot prompting","cz":"zero-shot prompting","def":"Prompt bez příkladu výstupu; model se opírá jen o znalosti z tréninku. Hodí se pro jednoduché a běžné úlohy.","kap":[2],"klicove":true,"href":"kapitola-2/vyklad.html#oddil-2-1-2"}]};
